import {pip,dot} from './broad-art.mjs';
import {foodArt} from './play-media.mjs';
import {sceneCaption} from './loft-content.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function puppetArt(id,action='wonders'){
 if(id==='pip')return pip(action==='offers'?'point':action==='wonders'?'think':'wave');
 if(id==='dot')return dot(action==='offers'?'point':action==='wonders'?'think':'wave');
 const shapes={
 rabbit:'<ellipse cx="43" cy="32" rx="12" ry="27" fill="#e2cf9f"/><ellipse cx="74" cy="32" rx="12" ry="27" fill="#e2cf9f"/><path d="M43 12v31m31-31v31" stroke="#da8d8d" stroke-width="7"/><ellipse cx="59" cy="85" rx="31" ry="29" fill="#e2cf9f"/><ellipse cx="59" cy="56" rx="31" ry="26" fill="#e2cf9f"/><ellipse cx="59" cy="94" rx="17" ry="18" fill="#fff3db"/>',
 kitten:'<path d="M83 92q33-40 14-44q-15 4-4 27" fill="none" stroke="#abc4da" stroke-width="13"/><path d="M28 52V18l23 15q9-4 19 0l22-15v34Z" fill="#abc4da"/><ellipse cx="59" cy="87" rx="29" ry="28" fill="#abc4da"/><ellipse cx="59" cy="54" rx="33" ry="26" fill="#abc4da"/><path d="m33 25 11 14-11 2m46-2 8-14v17" fill="#da8d8d"/><path d="m24 58 22 3m-21 5 21-2m27-3 23-3m-23 6 22 3"/>',
 dragon:'<path d="M32 65 7 42l5 45 28-3m48-19 24-23-5 45-27-3" fill="#b4a6c8"/><path d="m36 35-8-21 22 13m24 0 19-13-7 24" fill="#e9b84a"/><ellipse cx="60" cy="84" rx="33" ry="31" fill="#90b9ae"/><path d="M29 44q32-33 62 0v23q-30 32-62-2Z" fill="#90b9ae"/><ellipse cx="61" cy="94" rx="16" ry="18" fill="#e2cf9f"/>'
 };
 return `<svg viewBox="0 0 120 125" aria-hidden="true"><g stroke="#183f39" stroke-width="2" stroke-linejoin="round" stroke-linecap="round">${shapes[id]||shapes.rabbit}<circle cx="49" cy="53" r="2.5" fill="#183f39"/><circle cx="72" cy="53" r="2.5" fill="#183f39"/><path d="m57 62 4 3 4-3m-14 9q10 8 20 0M34 87l-12-5m64 5 13-5" fill="none"/></g></svg>`;
}
export function propArt(id){
 if(id==='moon')return foodArt('moon-crunch');
 const shapes={letter:'<rect x="13" y="27" width="74" height="50" rx="4" fill="#fffef9"/><path d="m15 29 35 28 35-28M15 75l25-25m45 25L61 50" fill="none"/><circle cx="50" cy="57" r="6" fill="#da8d8d"/>',umbrella:'<path d="M10 48q40-70 80 0q-13-12-26 0q-14-12-28 0q-13-12-26 0Z" fill="#e9b84a"/><path d="M50 13v65q-1 18-15 6" fill="none" stroke-width="4"/><path d="M50 16Q33 32 36 48m14-32q17 16 14 32" fill="none"/>',basket:'<path d="M14 45h72L76 87H24Z" fill="#c3a77b"/><path d="M28 46V32q22-31 44 0v14M18 56h63M22 70h57M35 47l3 38m24-38-3 38" fill="none" stroke-width="4"/>',blanket:'<path d="m13 30 62-8 13 63-63 6Z" fill="#b4a6c8"/><path d="m21 41 57-6m-53 22 57-7m-55 22 58-8M32 27l13 60m5-63 13 61" fill="none" stroke="#fffef9" stroke-width="4"/>',teacup:'<path d="M25 30h48v34q-24 31-48 0Z" fill="#da8d8d"/><path d="M73 35q31-1 15 28l-15 2M14 83h73" fill="none" stroke-width="5"/><path d="M39 22q-9-6 0-14m18 14q-9-6 0-14" fill="none" stroke-width="3"/>'};
 return `<svg viewBox="0 0 100 105" aria-hidden="true"><g stroke="#183f39" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${shapes[id]||shapes.letter}</g></svg>`;
}
export function backdropArt(place){
 const scenes={
 garden:'<path d="M0 190Q200 130 400 200Q600 145 800 180V400H0" fill="#b8d4c3"/><path d="M340 400 440 180h55L540 400" fill="#e2cf9f"/><g fill="#397958"><path d="M55 220V60h18v160"/><ellipse cx="66" cy="81" rx="73" ry="64"/><path d="M706 216V85h18v131"/><ellipse cx="711" cy="96" rx="79" ry="60"/></g><g fill="#e9b84a"><circle cx="163" cy="290" r="16"/><circle cx="653" cy="272" r="15"/></g><path d="M163 306v36m490-55v40" stroke="#397958" stroke-width="5"/>',
 cafe:'<path d="M0 0H800V235H0Z" fill="#e2cf9f"/><rect x="80" y="52" width="210" height="125" rx="9" fill="#abc4da" stroke="#397958" stroke-width="9"/><path d="M185 55v120M83 112h202" stroke="#fffef9" stroke-width="7"/><rect x="540" y="43" width="149" height="148" rx="4" fill="#397958"/><path d="M555 170h119" stroke="#e9b84a" stroke-width="4"/><path d="M0 242h800M0 310h800M0 380h800" stroke="#c3a77b" stroke-width="3"/><path d="M18 230h70v120m624-120h70v120" fill="none" stroke="#8b643b" stroke-width="9"/>',
 bridge:'<path d="M0 220Q400 128 800 220V400H0Z" fill="#b8d4c3"/><path d="M280 400Q240 240 402 141Q530 240 520 400Z" fill="#abc4da"/><path d="M115 300Q400 170 685 300l-15 55Q400 239 130 355Z" fill="#c3a77b" stroke="#8b643b" stroke-width="5"/><path d="M100 257Q400 120 700 257M147 241v88m129-130v83m130-103v85m130-65v86m129-42v90" fill="none" stroke="#8b643b" stroke-width="10"/>',
 log:'<path d="M0 180Q400 110 800 180V400H0Z" fill="#b8d4c3"/><path d="M38 280Q50 90 355 110L585 162v176L230 365Z" fill="#8b643b"/><ellipse cx="585" cy="250" rx="111" ry="102" fill="#c3a77b"/><ellipse cx="585" cy="250" rx="76" ry="72" fill="#183f39"/><path d="m72 213 353-44M68 265l362-29m-320 77 323-20" stroke="#695477" stroke-width="7"/><path d="M175 149q-15-100 72-99q83 18-19 114" fill="#397958"/><path d="M203 142 242 66" stroke="#90b9ae" stroke-width="5"/>'};
 return `<svg viewBox="0 0 800 400" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><rect width="800" height="400" fill="#edf3ef"/>${scenes[place]||scenes.garden}</svg>`;
}
export function sceneArt(frame,small=false){return `<div class="loft-proscenium ${small?'loft-mini':''}"><div class="loft-stage loft-action-${esc(frame.action)}" ${small?'aria-hidden="true"':`role="img" aria-label="${esc(sceneCaption(frame))}" data-loft-stage`}>${backdropArt(frame.place)}<div class="loft-puppet"><span class="loft-rod"></span>${puppetArt(frame.actor,frame.action)}</div><div class="loft-prop">${propArt(frame.prop)}</div>${frame.action==='wonders'?'<div class="loft-thought" aria-hidden="true">…</div>':''}<div class="loft-curtain" aria-hidden="true"></div></div></div>`;}
